import re

def compare_versions(a, b):
    def parse_version(version):
        # Split into main version and pre-release/build
        main, *rest = version.split('-', 1)
        main_parts = list(map(int, main.split('.')))
        pre_release = None
        if rest:
            pre_release = rest[0].split('+')[0]  # Ignore build metadata
            pre_parts = []
            for part in pre_release.split('.'):
                if part.isdigit():
                    pre_parts.append(int(part))
                else:
                    pre_parts.append(part)
        return main_parts, pre_parts

    main_a, pre_a = parse_version(a)
    main_b, pre_b = parse_version(b)

    # Compare main versions
    for ma, mb in zip(main_a, main_b):
        if ma < mb:
            return -1
        elif ma > mb:
            return 1
    if len(main_a) < len(main_b):
        return -1
    elif len(main_a) > len(main_b):
        return 1

    # If main versions are equal, compare pre-releases
    if pre_a is None and pre_b is None:
        return 0
    elif pre_a is None:
        return 1
    elif pre_b is None:
        return -1

    # Compare pre-release parts
    for pa, pb in zip(pre_a, pre_b):
        if isinstance(pa, int) and isinstance(pb, int):
            if pa < pb:
                return -1
            elif pa > pb:
                return 1
        elif isinstance(pa, int):
            return 1
        elif isinstance(pb, int):
            return -1
        else:
            if pa < pb:
                return -1
            elif pa > pb:
                return 1

    # If all shared parts are equal, shorter pre-release is lower
    if len(pre_a) < len(pre_b):
        return -1
    elif len(pre_a) > len(pre_b):
        return 1

    return 0
